import re

def remove_multiple_spaces(s: str) -> str:
    # Strip leading/trailing spaces first
    s = s.strip()
    # Replace one or more spaces with a single space
    return re.sub(r' +', ' ', s)

def is_decimal(s: str) -> bool:
    if not s:
        return False

    # Handle optional leading minus sign
    if s[0] == '-':
        s = s[1:]
        if not s:
            return False

    parts = s.split('.')
    if len(parts) != 2:
        return False

    int_part, frac_part = parts
    if not int_part.isdigit():
        return False
    if len(frac_part) != 2 or not frac_part.isdigit():
        return False

    return True

def is_Two_Alter(s: str) -> bool:
    if len(s) < 2:
        return False

    # Extract the two characters that should alternate
    first_char = s[0]
    second_char = s[1]

    # They must be distinct
    if first_char == second_char:
        return False

    # Check alternation
    for i, ch in enumerate(s):
        expected_char = first_char if i % 2 == 0 else second_char
        if ch != expected_char:
            return False
    return True

def max_sub_array_sum(arr, n):
    if n == 0:
        return 0

    max_ending_here = max_so_far = arr[0]
    for i in range(1, n):
        max_ending_here = max(arr[i], max_ending_here + arr[i])
        max_so_far = max(max_so_far, max_ending_here)

    return max_so_far

