def len_log(s: str) -> int:
    words = re.findall(r'[A-Za-z]+', s)
    if not words:
        return 0
    return max(len(word) for word in words)

def count_nums(arr):
    def signed_digit_sum(n):
        s = str(abs(n))
        digits = [int(d) for d in s]
        if n < 0:
            digits[0] = -digits[0]
        return sum(digits)

    return sum(1 for x in arr if signed_digit_sum(x) > 0)

