def largest_prime_factor(n: int):
    """Return the largest prime factor of n. Assume n > 1 and is not a prime.
    >>> largest_prime_factor(13195)
    29
    >>> largest_prime_factor(2048)
    2
    """
    if not isinstance(n, int) or n <= 1:
        raise ValueError("Input must be an integer greater than 1 and not prime.")

    # Quick primality check to reject prime n input
    def is_prime(x):
        if x < 2:
            return False
        if x in (2, 3):
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True

    if is_prime(n):
        raise ValueError("Input must not be prime.")

    # Factorization to find largest prime factor
    largest_factor = None
    # Remove factors of 2
    while n % 2 == 0:
        largest_factor = 2
        n //= 2

    # Check odd factors from 3 upwards
    factor = 3
    while factor * factor <= n:
        while n % factor == 0:
            largest_factor = factor
            n //= factor
        factor += 2

    # If n is still > 1, it is prime and the largest factor
    if n > 1:
        largest_factor = n

    return largest_factor

